import{_ as a,o,c as r,a2 as t}from"./chunks/framework.DzNHXt93.js";const m=JSON.parse('{"title":"EdgeKVNamespace — takoform_edge_kv_namespace","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/edge/edge-kv-namespace.md","filePath":"proposals/edge/edge-kv-namespace.md"}'),s={name:"proposals/edge/edge-kv-namespace.md"};function n(i,e,d,c,l,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="edgekvnamespace-—-takoform-edge-kv-namespace" tabindex="-1">EdgeKVNamespace — <code>takoform_edge_kv_namespace</code> <a class="header-anchor" href="#edgekvnamespace-—-takoform-edge-kv-namespace" aria-label="Permalink to &quot;EdgeKVNamespace — `takoform_edge_kv_namespace`&quot;">​</a></h1><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>A worker keeps small, read-heavy state — sessions, feature data, rendered fragments — in a key/value namespace replicated close to every point of presence. Workers consume it exclusively through <code>module-worker.edge-kv</code> bindings.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>identity</code>. The namespace has no desired fields: its semantics are entirely fixed by the <code>edge.kv</code> Interface.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p>Exactly the <code>edge.kv@1.0.0</code> contract: get/getWithMetadata/put/delete/list, eventual consistency, last-writer-wins per key, cursor pagination in lexicographic key order, closed errors, and portable minimum limits.</p><p>A value is opaque BYTES, carried in the family&#39;s encoded-bytes shape, so the declared byte limit and the structural string ceiling measure the same thing (decision 0020). Eventual consistency means what it says: a read that follows a write may return the previous value, or <code>not_found</code>, until replication converges — including a read the same client issues immediately after its own write. There is no read-your-writes guarantee and no session in which one holds; convergence is a host obligation rather than something the desired-state conformance lane proves.</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>Eventual consistency is the Form&#39;s semantics, not an option. Every consumer program is written against the convergence model; a consistency selector would hollow the contract out (decision 0008).</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>A per-key linearizable store, a cache with eviction, or a TTL-defaulted store each change the model a consumer can rely on and are different Forms.</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p><code>edge.kv@1.0.0</code>.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None; it is a binding target (<code>module-worker.edge-kv</code>).</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>Deleting a namespace bound by any Worker Version must fail with <code>dependency_in_use</code> (refuse_while_bound). Delete destroys all keys; there is no portable restore.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>The eventually consistent edge KV store of a proven edge platform. The retained v1alpha2 <code>KeyValueStore</code> candidate, whose open <code>consistency</code> enum this Form replaces by fixing one shape.</p>',20)])])}const u=a(s,[["render",n]]);export{m as __pageData,u as default};
